import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 최초 마감 상태는 '마감 취소'(미마감 의미)
const INITIAL_CLOSING_STATUS = '마감 취소';
const CLOSED_STATUS = '마감';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string') {
    return v.trim() !== '' && Number.isFinite(Number(v));
  }
  return false;
}

function isDate(v: unknown): boolean {
  return typeof v === 'string' && DATE_RE.test(v);
}

function isBlank(v: unknown): boolean {
  return v === null || v === undefined || v === '';
}

function amountOf(v: unknown, label: string): string | null {
  if (isBlank(v)) {
    return null;
  }
  if (!isNumeric(v)) {
    throw invalid(label + '은(는) 숫자로 입력해 주세요.');
  }
  if (Number(v) < 0) {
    throw invalid(label + '은(는) 0 이상이어야 합니다.');
  }
  return String(v);
}

function idOf(v: unknown, label: string): string {
  if (!isNumeric(v) || !Number.isInteger(Number(v))) {
    throw invalid(label + '을(를) 확인해 주세요.');
  }
  return String(v);
}

function dateOf(v: unknown, label: string): string {
  if (!isDate(v)) {
    throw invalid(label + '을(를) YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return v as string;
}

@Controller('api/v1')
export class FnSfr00903Controller {
  @Get('/fund-plans')
  async listFundPlans(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const page = isBlank(q['page']) ? 0 : Number(q['page']);
    const size = isBlank(q['size']) ? DEFAULT_SIZE : Number(q['size']);
    if (!Number.isInteger(page) || page < 0) {
      throw invalid('page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw invalid('size는 1 이상의 정수여야 합니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);
    const startDate = isBlank(q['startDate']) ? null : dateOf(q['startDate'], '계획 기간 시작');
    const endDate = isBlank(q['endDate']) ? null : dateOf(q['endDate'], '계획 기간 종료');
    const fundSubjectId = isBlank(q['fundSubjectId']) ? null : idOf(q['fundSubjectId'], '자금과목');
    const filters = { startDate, endDate, fundSubjectId };
    const where =
      ' WHERE (CAST(:startDate AS date) IS NULL OR plan_start_date >= CAST(:startDate AS date))' +
      ' AND (CAST(:endDate AS date) IS NULL OR plan_end_date <= CAST(:endDate AS date))' +
      ' AND (CAST(:fundSubjectId AS bigint) IS NULL OR fund_subject_id = CAST(:fundSubjectId AS bigint))';
    return transaction(async (db) => {
      const counted = await db.query('SELECT COUNT(*) AS total FROM fund_plan' + where, filters);
      const items = await db.query(
        'SELECT fund_plan_id AS "fundPlanId", fund_subject_id AS "fundSubjectId",' +
          ' plan_start_date AS "planStartDate", plan_end_date AS "planEndDate",' +
          ' income_amount AS "incomeAmount", expense_amount AS "expenseAmount",' +
          ' remark AS "remark", closing_status AS "closingStatus",' +
          ' COALESCE(income_amount, 0) - COALESCE(expense_amount, 0) AS "balanceDifference"' +
          ' FROM fund_plan' + where +
          ' ORDER BY plan_start_date DESC, fund_plan_id DESC' +
          ' LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { ...filters, size: pageSize, offset: page * pageSize },
      );
      return { items, page, size: pageSize, total: Number(counted[0].total) };
    });
  }

  @Post('/fund-plans')
  @HttpCode(200)
  async createFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const fundSubjectId = idOf(data['fundSubjectId'], '자금과목');
    const planStartDate = dateOf(data['planStartDate'], '계획 시작일');
    const planEndDate = dateOf(data['planEndDate'], '계획 종료일');
    const incomeAmount = amountOf(data['incomeAmount'], '수입 계획 금액');
    const expenseAmount = amountOf(data['expenseAmount'], '지출 계획 금액');
    const remark = isBlank(data['remark']) ? null : String(data['remark']);
    return transaction(async (db) => {
      const subjects = await db.query(
        'SELECT fund_subject_id FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
        { fundSubjectId },
      );
      if (subjects.length === 0) {
        throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목을 찾을 수 없습니다.');
      }
      const ranges = await db.query(
        'SELECT (CAST(:planEndDate AS date) < CAST(:planStartDate AS date)) AS "bad"',
        { planStartDate, planEndDate },
      );
      if (ranges[0].bad) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '계획 종료일은 시작일보다 빠를 수 없습니다.');
      }
      const dups = await db.query(
        'SELECT fund_plan_id FROM fund_plan WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)' +
          ' AND plan_start_date = CAST(:planStartDate AS date) AND plan_end_date = CAST(:planEndDate AS date)',
        { fundSubjectId, planStartDate, planEndDate },
      );
      if (dups.length > 0) {
        throw new ApiError(409, 'DUPLICATE_FUND_PLAN', '같은 자금과목과 기간의 계획이 이미 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO fund_plan (fund_subject_id, plan_start_date, plan_end_date, income_amount,' +
          ' expense_amount, remark, closing_status, created_at, updated_at)' +
          ' VALUES (CAST(:fundSubjectId AS bigint), CAST(:planStartDate AS date), CAST(:planEndDate AS date),' +
          ' CAST(:incomeAmount AS numeric), CAST(:expenseAmount AS numeric), :remark, :closingStatus, now(), now())' +
          ' RETURNING fund_plan_id AS "fundPlanId"',
        {
          fundSubjectId,
          planStartDate,
          planEndDate,
          incomeAmount,
          expenseAmount,
          remark,
          closingStatus: INITIAL_CLOSING_STATUS,
        },
      );
      return { fundPlanId: Number(rows[0].fundPlanId) };
    });
  }

  @Patch('/fund-plans/:fundPlanId')
  async updateFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['fundPlanId'], '자금수지계획 ID');
    const data = checks.inputOf(req.body);
    const hasSubject = 'fundSubjectId' in data;
    const hasStart = 'planStartDate' in data;
    const hasEnd = 'planEndDate' in data;
    const hasIncome = 'incomeAmount' in data;
    const hasExpense = 'expenseAmount' in data;
    const hasRemark = 'remark' in data;
    const fundSubjectId = hasSubject ? idOf(data['fundSubjectId'], '자금과목') : null;
    const planStartDate = hasStart ? dateOf(data['planStartDate'], '계획 시작일') : null;
    const planEndDate = hasEnd ? dateOf(data['planEndDate'], '계획 종료일') : null;
    const incomeAmount = hasIncome ? amountOf(data['incomeAmount'], '수입 계획 금액') : null;
    const expenseAmount = hasExpense ? amountOf(data['expenseAmount'], '지출 계획 금액') : null;
    const remark = hasRemark && !isBlank(data['remark']) ? String(data['remark']) : null;
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closing_status AS "closingStatus" FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FUND_PLAN_NOT_FOUND', '자금수지계획을 찾을 수 없습니다.');
      }
      if (found[0].closingStatus === CLOSED_STATUS) {
        throw new ApiError(409, 'FUND_PLAN_CLOSED', '마감된 기간의 계획은 마감을 취소한 뒤에 수정할 수 있습니다.');
      }
      if (hasSubject) {
        const subjects = await db.query(
          'SELECT fund_subject_id FROM fund_subject WHERE fund_subject_id = CAST(:fundSubjectId AS bigint)',
          { fundSubjectId },
        );
        if (subjects.length === 0) {
          throw new ApiError(404, 'FUND_SUBJECT_NOT_FOUND', '자금과목을 찾을 수 없습니다.');
        }
      }
      const ranges = await db.query(
        'SELECT ((CASE WHEN CAST(:hasEnd AS boolean) THEN CAST(:planEndDate AS date) ELSE plan_end_date END)' +
          ' < (CASE WHEN CAST(:hasStart AS boolean) THEN CAST(:planStartDate AS date) ELSE plan_start_date END)) AS "bad"' +
          ' FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint)',
        { id, hasStart, hasEnd, planStartDate, planEndDate },
      );
      if (ranges[0].bad) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '계획 종료일은 시작일보다 빠를 수 없습니다.');
      }
      await db.execute(
        'UPDATE fund_plan SET' +
          ' fund_subject_id = CASE WHEN CAST(:hasSubject AS boolean) THEN CAST(:fundSubjectId AS bigint) ELSE fund_subject_id END,' +
          ' plan_start_date = CASE WHEN CAST(:hasStart AS boolean) THEN CAST(:planStartDate AS date) ELSE plan_start_date END,' +
          ' plan_end_date = CASE WHEN CAST(:hasEnd AS boolean) THEN CAST(:planEndDate AS date) ELSE plan_end_date END,' +
          ' income_amount = CASE WHEN CAST(:hasIncome AS boolean) THEN CAST(:incomeAmount AS numeric) ELSE income_amount END,' +
          ' expense_amount = CASE WHEN CAST(:hasExpense AS boolean) THEN CAST(:expenseAmount AS numeric) ELSE expense_amount END,' +
          ' remark = CASE WHEN CAST(:hasRemark AS boolean) THEN :remark ELSE remark END,' +
          ' updated_at = now()' +
          ' WHERE fund_plan_id = CAST(:id AS bigint)',
        {
          id,
          hasSubject,
          hasStart,
          hasEnd,
          hasIncome,
          hasExpense,
          hasRemark,
          fundSubjectId,
          planStartDate,
          planEndDate,
          incomeAmount,
          expenseAmount,
          remark,
        },
      );
      return { fundPlanId: Number(id) };
    });
  }

  @Delete('/fund-plans/:fundPlanId')
  async deleteFundPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = idOf(req.params['fundPlanId'], '자금수지계획 ID');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closing_status AS "closingStatus" FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FUND_PLAN_NOT_FOUND', '자금수지계획을 찾을 수 없습니다.');
      }
      if (found[0].closingStatus === CLOSED_STATUS) {
        throw new ApiError(409, 'FUND_PLAN_CLOSED', '마감된 기간의 계획은 마감을 취소한 뒤에 삭제할 수 있습니다.');
      }
      await db.execute('DELETE FROM fund_plan WHERE fund_plan_id = CAST(:id AS bigint)', { id });
      return {};
    });
  }
}

