import { useState } from 'react';
import { call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field, NumberInput, DateInput, TextInput, LookupSelect, RefName, ErrorText } from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const CLOSED = '마감';

interface DrawerState {
  kind: 'create' | 'edit' | 'delete';
  row?: Row;
}

function checkAmount(v: unknown, label: string) {
  if (typeof v === 'string' && v !== '') {
    throw new Error(label + '은(는) 숫자로 입력해 주세요.');
  }
  if (typeof v === 'number' && v < 0) {
    throw new Error(label + '은(는) 0 이상이어야 합니다.');
  }
}

function PlanForm({ role, row, onDone }: { role: string; row?: Row; onDone: () => void }) {
  const [fundSubjectId, setFundSubjectId] = useState<unknown>(row ? row['fundSubjectId'] : '');
  const [planStartDate, setPlanStartDate] = useState<unknown>(row ? row['planStartDate'] : '');
  const [planEndDate, setPlanEndDate] = useState<unknown>(row ? row['planEndDate'] : '');
  const [incomeAmount, setIncomeAmount] = useState<unknown>(row ? row['incomeAmount'] ?? '' : '');
  const [expenseAmount, setExpenseAmount] = useState<unknown>(row ? row['expenseAmount'] ?? '' : '');
  const [remark, setRemark] = useState<unknown>(row ? row['remark'] ?? '' : '');

  async function submit() {
    if (!fundSubjectId) {
      throw new Error('자금과목을 선택해 주세요.');
    }
    if (!planStartDate) {
      throw new Error('계획 시작일을 입력해 주세요.');
    }
    if (!planEndDate) {
      throw new Error('계획 종료일을 입력해 주세요.');
    }
    checkAmount(incomeAmount, '수입 계획 금액');
    checkAmount(expenseAmount, '지출 계획 금액');
    const body: Row = {
      fundSubjectId,
      planStartDate,
      planEndDate,
      incomeAmount: incomeAmount === '' ? null : incomeAmount,
      expenseAmount: expenseAmount === '' ? null : expenseAmount,
      remark: remark === '' ? null : remark,
    };
    if (row) {
      await call('PATCH', '/fund-plans/' + String(row['fundPlanId']), role, body);
    } else {
      await call('POST', '/fund-plans', role, body);
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={row ? '수정 저장' : '등록'}>
      <Field label='자금과목' required>
        <LookupSelect table='fund_subject' role={role} value={fundSubjectId} onChange={setFundSubjectId} />
      </Field>
      <Field label='계획 시작일' required>
        <DateInput value={planStartDate} onChange={setPlanStartDate} />
      </Field>
      <Field label='계획 종료일' required>
        <DateInput value={planEndDate} onChange={setPlanEndDate} />
      </Field>
      <Field label='수입 계획 금액'>
        <NumberInput value={incomeAmount} onChange={setIncomeAmount} />
      </Field>
      <Field label='지출 계획 금액'>
        <NumberInput value={expenseAmount} onChange={setExpenseAmount} />
      </Field>
      <Field label='비고' wide>
        <TextInput value={remark} onChange={setRemark} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr00903Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState<unknown>('');
  const [endDate, setEndDate] = useState<unknown>('');
  const [subject, setSubject] = useState<unknown>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [drawer, setDrawer] = useState<DrawerState | null>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/fund-plans', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page],
  );

  function search() {
    setPage(0);
    setApplied({ startDate, endDate, fundSubjectId: subject });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setSubject('');
    setPage(0);
    setApplied({});
  }

  function done(text: string) {
    setDrawer(null);
    setDetail(null);
    notify(text);
    reload();
  }

  const columns: Column[] = [
    { key: 'fundSubjectId', label: '자금과목', render: (r) => <RefName table='fund_subject' role={role} value={r['fundSubjectId']} /> },
    {
      key: 'planStartDate',
      label: '계획 기간',
      render: (r) => (
        <span>
          <DateText value={r['planStartDate']} /> ~ <DateText value={r['planEndDate']} />
        </span>
      ),
    },
    { key: 'incomeAmount', label: '수입 계획 금액', render: (r) => <Num value={r['incomeAmount']} /> },
    { key: 'expenseAmount', label: '지출 계획 금액', render: (r) => <Num value={r['expenseAmount']} /> },
    { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
  ];

  const closed = detail ? detail['closingStatus'] === CLOSED : false;

  return (
    <div>
      {detail ? (
        <div className='doc'>
          <button className='ghost' onClick={() => setDetail(null)}>목록으로 돌아가기</button>
          <section className='box'>
            <h2>자금수지계획</h2>
            <Pairs
              items={[
                ['자금과목', <RefName table='fund_subject' role={role} value={detail['fundSubjectId']} />],
                ['계획 시작일', <DateText value={detail['planStartDate']} />],
                ['계획 종료일', <DateText value={detail['planEndDate']} />],
                ['수입 계획 금액', <Num value={detail['incomeAmount']} />],
                ['지출 계획 금액', <Num value={detail['expenseAmount']} />],
                ['수지 차액', <Num value={detail['balanceDifference']} />],
                ['마감 상태', <Badge value={detail['closingStatus']} />],
                ['비고', String(detail['remark'] ?? '')],
              ]}
            />
          </section>
          {closed ? (
            <p>마감된 기간의 계획입니다. 수정하거나 삭제하려면 먼저 마감을 취소해 주세요.</p>
          ) : (
            <div>
              <button onClick={() => setDrawer({ kind: 'edit', row: detail })}>수정</button>
              <button className='ghost' onClick={() => setDrawer({ kind: 'delete', row: detail })}>삭제</button>
            </div>
          )}
        </div>
      ) : (
        <div className='doc'>
          <h2>자금수지계획</h2>
          <Filters onSearch={search} onReset={reset}>
            <Field label='계획 기간 시작'>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label='계획 기간 종료'>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label='자금과목'>
              <LookupSelect table='fund_subject' role={role} value={subject} onChange={setSubject} />
            </Field>
          </Filters>
          <Band total={data ? data.total : undefined}>
            <button onClick={() => setDrawer({ kind: 'create' })}>자금수지계획 등록</button>
          </Band>
          {error ? <ErrorText text={error} /> : null}
          {loading ? <p>불러오는 중입니다.</p> : null}
          <DataTable
            columns={columns}
            rows={data ? data.items : []}
            onRowClick={(r) => setDetail(r)}
            empty='아직 등록한 자금수지계획이 없습니다. 자금수지계획 등록 버튼으로 첫 계획을 만들어 보세요.'
          />
          <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
        </div>
      )}
      {drawer && drawer.kind === 'create' ? (
        <Drawer title='자금수지계획 등록' onClose={() => setDrawer(null)}>
          <PlanForm role={role} onDone={() => done('자금수지계획을 등록했습니다.')} />
        </Drawer>
      ) : null}
      {drawer && drawer.kind === 'edit' ? (
        <Drawer title='자금수지계획 수정' onClose={() => setDrawer(null)}>
          <PlanForm role={role} row={drawer.row} onDone={() => done('자금수지계획을 수정했습니다.')} />
        </Drawer>
      ) : null}
      {drawer && drawer.kind === 'delete' && drawer.row ? (
        <Drawer title='자금수지계획 삭제' onClose={() => setDrawer(null)}>
          <Form
            danger
            submit='삭제'
            note='삭제한 자금수지계획은 되돌릴 수 없습니다.'
            onSubmit={async () => {
              await call('DELETE', '/fund-plans/' + String(drawer.row ? drawer.row['fundPlanId'] : ''), role);
              done('자금수지계획을 삭제했습니다.');
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
